 if(s.type==='knn')return sel('k','参考几个邻居？',[[1,'K = 1'],[3,'K = 3'],[5,'K = 5'],[9,'K = 9']],s.k)+(s.v==='features'?sel('feature','用于判断的信息',[[0,'随机编号'],[1,'重量 + 甜度（已归一化）']],+s.feature):'')+(['draw','lab'].includes(s.v)?sel('label','点画布添加样本',[[0,'● 苹果 / 类别 A'],[1,'● 橘子 / 类别 B']],s.label)+btn('clear','清空数据'):'')+(s.v==='balance'?btn('balance','补充橘子样本','primary'):'')+`<small>${s.v==='dirty'?'点中一个样本可翻转标签。':'绿色 = A，橙色 = B；蓝色十字为待分类点。'}</small>`;
 if(s.type==='reg')return (s.v==='overfit'?sel('model','选择模型',[['memory','只记忆训练样本'],['line','学习一条直线']],s.model):'')+range('w','斜率 w',-1,2,.01,s.w)+range('b','截距 b',-.5,1,.01,s.b)+(s.v!=='manual'?range('lr','学习率',.01,2,.01,s.lr)+btn('train','自动训练 80 步','primary'):'');
