 if(s.type==='conv')return sel('filter','选择 3 × 3 卷积核',[['blur','均值模糊'],['vertical','竖直边缘'],['horizontal','水平边缘']],s.filter)+btn('scan','计算特征图','primary');
 if(s.type==='vision')return sel('label','当前收集的类别',[[0,'A · 竖线（也可自定义）'],[1,'B · 横线（也可自定义）']],s.label)+`<div class="row">${btn('sample','保存这张样本')}${btn('clear','清空画布')}${btn('vertical','画竖线')}${btn('horizontal','画横线')}</div><div class="row" style="margin-top:12px">${btn('augment',s.aug?'✓ 平移增强已开启':'开启平移增强')}${btn('train','训练识别器','primary')}${btn('predict','识别当前图')}</div><small>点击格子绘图。A: ${s.samples.filter(p=>!p.c).length} 张 · B: ${s.samples.filter(p=>p.c).length} 张；训练后请重新画图再测试。</small>`;
 if(s.type==='rl')return `<div class="maze-diagnostic">${Algo.mazeDistance(s.walls)===null?'当前地图没有通往终点的道路。移除一些障碍，或恢复地图，再训练。':`地图可通行 · 最短可行路径 ${Algo.mazeDistance(s.walls)} 步。训练仍需通过试错学习。`}<button class="secondary" onclick="act('restoremap')">恢复初始地图</button></div>`+range('eps','探索率 ε',0,1,.05,s.eps)+range('reward','终点奖励',-2,15,1,s.reward)+`<div class="row">${btn('train','训练 150 回合','primary')}${btn('route','播放当前策略')}${btn('obstacle','改变道路')}</div><small>绿色格为测试路径；点格子也可改变障碍（起终点除外）。</small>`;
