 if(s.type==='go'){let r=Algo.rng(123),data=[];for(let g=0;g<70;g++){let b=Array(25).fill(0),color=1;for(let m=0;m<20;m++){let legal=b.map((_,i)=>Algo.move(b,i,color)).filter(Boolean);if(!legal.length)break;let move=legal[Math.floor(r()*legal.length)];data.push({x:move.features,y:move.captures/4});b=move.board;color=3-color}}for(let e=0;e<100;e++){let loss=0;for(let p of data){let pred=s.weights.reduce((v,w,i)=>v+w*p.x[i],0),d=pred-p.y;loss+=d*d;s.weights=s.weights.map((w,i)=>w-.04*d*p.x[i])}s.loss.push(loss/data.length)}s.trained++;s.message=`已用 ${data.length} 个合法落子样本学习一步提子数。特征中含提子数，所以这是刻意简化的回归练习，不代表学会长期棋力。现在点棋盘落子。`}
