 if(a==='restoremap'&&s.type==='rl'){Object.assign(s,{walls:[6,11,16,8,13],q:Array.from({length:25},()=>[0,0,0,0]),trained:0,episodes:0,history:[],path:[],changed:false,trainingError:false,message:'初始地图已恢复，旧地图的策略已清空。重新训练以学习可行路线。'})}
