 if(s.type==='knn'){let q=s.query,neighbors=[...s.train].sort((a,b)=>(a.x-q.x)**2+(a.y-q.y)**2-((b.x-q.x)**2+(b.y-q.y)**2)).slice(0,s.k);c.setLineDash([4,4]);c.strokeStyle='#789dae';if(s.feature)for(let p of neighbors){c.beginPath();c.moveTo(px(q.x),py(q.y));c.lineTo(px(p.x),py(p.y));c.stroke()}c.setLineDash([]);c.lineWidth=3;c.beginPath();c.moveTo(px(q.x)-7,py(q.y));c.lineTo(px(q.x)+7,py(q.y));c.moveTo(px(q.x),py(q.y)-7);c.lineTo(px(q.x),py(q.y)+7);c.stroke()}
